[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="A neighborhood grocery store offering unique, high-quality food products at great prices.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green: #2D6A4F;
      --green-dark: #1B4332;
      --green-light: #40916C;
      --orange: #F4A261;
      --orange-dark: #E76F51;
      --cream: #FEFAE0;
      --cream-dark: #F5F0D0;
      --terracotta: #E07A5F;
      --yellow: #F2CC8F;
      --white: #FFFFFF;
      --text-dark: #264653;
      --text-mid: #4A6C6F;
      --text-light: #6B8F8F;
      --shadow-sm: 0 2px 8px rgba(45, 106, 79, 0.08);
      --shadow-md: 0 4px 16px rgba(45, 106, 79, 0.12);
      --shadow-lg: 0 8px 32px rgba(45, 106, 79, 0.16);
      --radius-sm: 12px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--cream);
      color: var(--text-dark);
      line-height: 1.6;
      overflow-x: hidden;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Nunito', sans-serif;
      line-height: 1.2;
    }

    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; border: none; font-family: inherit; }
    input { font-family: inherit; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ========== HEADER ========== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.08);
      padding: 0 24px;
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.5rem;
      color: var(--green);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
    }

    .nav-links {
      display: flex;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 500;
      font-size: 0.95rem;
      color: var(--text-mid);
      transition: color var(--transition);
      position: relative;
    }

    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--green);
      border-radius: 2px;
      transition: width var(--transition);
    }

    .nav-links a:hover { color: var(--green); }
    .nav-links a:hover::after { width: 100%; }

    .header-cta {
      background: var(--green);
      color: var(--white);
      padding: 10px 22px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 0.9rem;
      transition: all var(--transition);
    }

    .header-cta:hover {
      background: var(--green-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      width: 40px;
      height: 40px;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 5px;
    }

    .mobile-menu-btn span {
      width: 24px;
      height: 2px;
      background: var(--green);
      border-radius: 2px;
      transition: var(--transition);
    }

    /* ========== HERO ========== */
    .hero {
      padding: 80px 24px 100px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -150px;
      left: -150px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(45, 106, 79, 0.08) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .hero-content { position: relative; z-index: 1; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(45, 106, 79, 0.08);
      color: var(--green);
      padding: 8px 16px;
      border-radius: 50px;
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 24px;
    }

    .hero h1 {
      font-size: 3.5rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero h1 span {
      color: var(--orange);
      position: relative;
    }

    .hero p {
      font-size: 1.15rem;
      color: var(--text-mid);
      max-width: 480px;
      margin-bottom: 36px;
      line-height: 1.7;
    }

    .hero-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .btn-primary {
      background: var(--green);
      color: var(--white);
      padding: 14px 32px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 1rem;
      transition: all var(--transition);
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: var(--shadow-lg);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--green);
      padding: 14px 32px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 1rem;
      border: 2px solid rgba(45, 106, 79, 0.15);
      transition: all var(--transition);
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .btn-secondary:hover {
      border-color: var(--green);
      transform: translateY(-2px);
      box-shadow: var(--shadow-sm);
    }

    .hero-visual {
      position: relative;
      z-index: 1;
    }

    .hero-image-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .hero-img-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      aspect-ratio: 1;
      position: relative;
    }

    .hero-img-card:nth-child(2) { margin-top: 32px; }
    .hero-img-card:nth-child(3) { margin-top: -32px; }

    .hero-img-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .hero-img-placeholder.img1 { background: linear-gradient(135deg, #A7C957, #6A994E); }
    .hero-img-placeholder.img2 { background: linear-gradient(135deg, #F4A261, #E76F51); }
    .hero-img-placeholder.img3 { background: linear-gradient(135deg, #E9C46A, #F4A261); }
    .hero-img-placeholder.img4 { background: linear-gradient(135deg, #2A9D8F, #264653); }

    .hero-float-card {
      position: absolute;
      bottom: 24px;
      left: -20px;
      background: var(--white);
      border-radius: var(--radius-sm);
      padding: 14px 20px;
      box-shadow: var(--shadow-lg);
      display: flex;
      align-items: center;
      gap: 12px;
      animation: float 3s ease-in-out infinite;
    }

    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    .hero-float-icon {
      width: 44px;
      height: 44px;
      background: rgba(45, 106, 79, 0.1);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
    }

    .hero-float-text strong {
      display: block;
      font-family: 'Nunito', sans-serif;
      font-size: 0.95rem;
      color: var(--green-dark);
    }

    .hero-float-text span {
      font-size: 0.8rem;
      color: var(--text-light);
    }

    /* ========== FEATURED PRODUCTS ========== */
    .featured {
      padding: 80px 0;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
      padding: 0 24px;
    }

    .section-header h2 {
      font-size: 2.2rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 1.05rem;
      color: var(--text-mid);
      max-width: 520px;
      margin: 0 auto;
    }

    .carousel-wrapper {
      position: relative;
      padding: 0 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .carousel-track-container {
      overflow: hidden;
      border-radius: var(--radius-md);
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      padding: 8px 0;
    }

    .product-card {
      min-width: 260px;
      background: var(--white);
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
      flex-shrink: 0;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-img {
      width: 100%;
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      position: relative;
    }

    .product-img .product-badge {
      position: absolute;
      top: 12px;
      left: 12px;
      background: var(--orange);
      color: var(--white);
      font-size: 0.7rem;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 50px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .product-info {
      padding: 20px;
    }

    .product-info h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--green-dark);
      margin-bottom: 6px;
    }

    .product-info .product-desc {
      font-size: 0.85rem;
      color: var(--text-light);
      margin-bottom: 14px;
      line-height: 1.5;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-size: 1.2rem;
      font-weight: 800;
      color: var(--green);
    }

    .product-add-btn {
      width: 36px;
      height: 36px;
      background: rgba(45, 106, 79, 0.08);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--green);
      font-size: 1.2rem;
      transition: all var(--transition);
    }

    .product-add-btn:hover {
      background: var(--green);
      color: var(--white);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      background: var(--white);
      border-radius: 50%;
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      color: var(--green);
      transition: all var(--transition);
      z-index: 2;
    }

    .carousel-btn:hover {
      background: var(--green);
      color: var(--white);
      box-shadow: var(--shadow-lg);
    }

    .carousel-btn.prev { left: 8px; }
    .carousel-btn.next { right: 8px; }

    .carousel-btn:disabled {
      opacity: 0.3;
      cursor: not-allowed;
    }

    .carousel-btn:disabled:hover {
      background: var(--white);
      color: var(--green);
    }

    /* ========== SEASONAL PICKS ========== */
    .seasonal {
      padding: 80px 24px;
    }

    .seasonal-inner {
      max-width: 1200px;
      margin: 0 auto;
      background: linear-gradient(135deg, var(--green) 0%, var(--green-light) 100%);
      border-radius: var(--radius-lg);
      padding: 64px;
      position: relative;
      overflow: hidden;
    }

    .seasonal-inner::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -100px;
      width: 300px;
      height: 300px;
      background: rgba(255,255,255,0.05);
      border-radius: 50%;
    }

    .seasonal-inner::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -80px;
      width: 250px;
      height: 250px;
      background: rgba(255,255,255,0.03);
      border-radius: 50%;
    }

    .seasonal-header {
      text-align: center;
      margin-bottom: 48px;
      position: relative;
      z-index: 1;
    }

    .seasonal-header h2 {
      font-size: 2.2rem;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 12px;
    }

    .seasonal-header p {
      font-size: 1.05rem;
      color: rgba(255,255,255,0.8);
      max-width: 480px;
      margin: 0 auto;
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
      position: relative;
      z-index: 1;
    }

    .seasonal-card {
      background: rgba(255,255,255,0.12);
      backdrop-filter: blur(8px);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: var(--radius-md);
      padding: 24px;
      transition: all var(--transition);
    }

    .seasonal-card:hover {
      background: rgba(255,255,255,0.2);
      transform: translateY(-4px);
    }

    .seasonal-card-emoji {
      font-size: 2.5rem;
      margin-bottom: 16px;
    }

    .seasonal-card h3 {
      font-size: 1rem;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 8px;
    }

    .seasonal-card p {
      font-size: 0.85rem;
      color: rgba(255,255,255,0.7);
      margin-bottom: 16px;
      line-height: 1.5;
    }

    .seasonal-card .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-size: 1.3rem;
      font-weight: 800;
      color: var(--yellow);
    }

    /* ========== CATEGORIES ========== */
    .categories {
      padding: 80px 24px;
    }

    .categories-grid {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      aspect-ratio: 3/4;
      cursor: pointer;
      transition: transform var(--transition);
    }

    .category-card:hover {
      transform: scale(1.05);
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
    }

    .cat-bg-1 { background: linear-gradient(145deg, #F2CC8F, #E9C46A); }
    .cat-bg-2 { background: linear-gradient(145deg, #A7C957, #6A994E); }
    .cat-bg-3 { background: linear-gradient(145deg, #90DBF4, #48CAE4); }
    .cat-bg-4 { background: linear-gradient(145deg, #F4A261, #E76F51); }
    .cat-bg-5 { background: linear-gradient(145deg, #FFE8D6, #DDBEA9); }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(0deg, rgba(27, 67, 50, 0.85) 0%, rgba(27, 67, 50, 0.2) 60%, transparent 100%);
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 24px;
      transition: all var(--transition);
    }

    .category-card:hover .category-overlay {
      background: linear-gradient(0deg, rgba(27, 67, 50, 0.92) 0%, rgba(27, 67, 50, 0.4) 70%, rgba(27, 67, 50, 0.1) 100%);
    }

    .category-overlay h3 {
      color: var(--white);
      font-size: 1.1rem;
      font-weight: 700;
      margin-bottom: 4px;
    }

    .category-overlay p {
      color: rgba(255,255,255,0.7);
      font-size: 0.8rem;
      line-height: 1.4;
      opacity: 0;
      transform: translateY(8px);
      transition: all var(--transition);
    }

    .category-card:hover .category-overlay p {
      opacity: 1;
      transform: translateY(0);
    }

    /* ========== BRAND HIGHLIGHTS ========== */
    .highlights {
      padding: 60px 24px;
    }

    .highlights-inner {
      max-width: 1200px;
      margin: 0 auto;
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 56px 40px;
      box-shadow: var(--shadow-md);
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
    }

    .highlight-item {
      text-align: center;
      position: relative;
    }

    .highlight-item:not(:last-child)::after {
      content: '';
      position: absolute;
      right: -20px;
      top: 10%;
      height: 80%;
      width: 1px;
      background: rgba(45, 106, 79, 0.1);
    }

    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-size: 2.8rem;
      font-weight: 800;
      color: var(--green);
      line-height: 1;
      margin-bottom: 8px;
    }

    .highlight-label {
      font-size: 0.95rem;
      font-weight: 600;
      color: var(--text-dark);
      margin-bottom: 6px;
    }

    .highlight-desc {
      font-size: 0.8rem;
      color: var(--text-light);
      line-height: 1.4;
    }

    /* ========== STORE LOCATOR ========== */
    .store-locator {
      padding: 80px 24px;
    }

    .store-locator-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
    }

    .store-locator h2 {
      font-size: 2.2rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 12px;
    }

    .store-locator > .store-locator-inner > p {
      font-size: 1.05rem;
      color: var(--text-mid);
      margin-bottom: 36px;
    }

    .store-search-form {
      display: flex;
      gap: 12px;
      max-width: 460px;
      margin: 0 auto 40px;
    }

    .store-search-form input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid rgba(45, 106, 79, 0.12);
      border-radius: 50px;
      font-size: 1rem;
      background: var(--white);
      color: var(--text-dark);
      outline: none;
      transition: border-color var(--transition);
    }

    .store-search-form input:focus {
      border-color: var(--green);
    }

    .store-search-form input::placeholder {
      color: var(--text-light);
    }

    .store-search-form button {
      background: var(--green);
      color: var(--white);
      padding: 14px 28px;
      border-radius: 50px;
      font-weight: 600;
      font-size: 1rem;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .store-search-form button:hover {
      background: var(--green-dark);
      box-shadow: var(--shadow-md);
    }

    .store-results {
      display: none;
    }

    .store-results.visible {
      display: block;
      animation: fadeSlideUp 0.4s ease;
    }

    @keyframes fadeSlideUp {
      from { opacity: 0; transform: translateY(16px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .store-card {
      background: var(--white);
      border-radius: var(--radius-md);
      padding: 24px;
      margin-bottom: 16px;
      box-shadow: var(--shadow-sm);
      display: grid;
      grid-template-columns: auto 1fr auto;
      gap: 20px;
      align-items: center;
      text-align: left;
      transition: all var(--transition);
    }

    .store-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .store-icon-wrap {
      width: 52px;
      height: 52px;
      background: rgba(45, 106, 79, 0.08);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
    }

    .store-details h4 {
      font-size: 1rem;
      font-weight: 700;
      color: var(--green-dark);
      margin-bottom: 4px;
    }

    .store-details p {
      font-size: 0.85rem;
      color: var(--text-mid);
      margin-bottom: 2px;
    }

    .store-distance {
      font-family: 'Nunito', sans-serif;
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--orange);
      white-space: nowrap;
    }

    /* ========== NEWSLETTER ========== */
    .newsletter {
      padding: 80px 24px;
    }

    .newsletter-inner {
      max-width: 1200px;
      margin: 0 auto;
      background: linear-gradient(135deg, var(--orange) 0%, var(--terracotta) 100%);
      border-radius: var(--radius-lg);
      padding: 64px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .newsletter-inner::before {
      content: '';
